    \BlankLine
    \For {$i\leftarrow 0$ \KwTo $G.length()$} {
      $\left\langle k_{out}\right\rangle \leftarrow$ \texttt{get\_outdegree}($n_p$)\;
      \eIf {$\left\langle k_{out}\right\rangle == 0$} {
        logPr[ i ] $\leftarrow$ logPr[ i ] + $\log( 1 / n )$\;
      }{
        $p_i(x) = (1-\alpha) / n$\;
                  $Pd_{x_j} \leftarrow$ \texttt{get\_prob\_distribution}$(G_i,~x_j)$\;
                  $S_{x_j} \leftarrow$ \texttt{get\_successors}$(G_i,~x_j)$\;
        \If {$x_k \in S_{x_j}$} {
          $p_i(x) \leftarrow p_i(x) + \alpha * Pd_{x_j}(x_k)$\;
        }
        logPr[ i ] $\leftarrow$ logPr[ i ] + $\log( p_i(x) )$\;
      }
    }
  }
  \Return{}~logPr
